export function getTRMLAProfile(acNo: number): MLAProfile | undefined {
  return TR_MLA_PROFILES.find(p => p.acNo === acNo);
}

export function getTRMLAsByParty(party: string): MLAProfile[] {
  return TR_MLA_PROFILES.filter(p => p.party === party);
}

export function getTRFemaleMLAs(): MLAProfile[] {
  return TR_MLA_PROFILES.filter(p => p.gender === 'F');
}
